-- Advanced planning, budgeting, control and performance fields for AgriCapital 360
alter table public.strategic_plans add column if not exists planning_horizon text not null default 'annual', add column if not exists period_start date, add column if not exists period_end date, add column if not exists scenario_name text not null default 'Base', add column if not exists version_number integer not null default 1, add column if not exists submitted_at timestamptz, add column if not exists closed_at timestamptz, add column if not exists review_notes text, add column if not exists currency_code text not null default 'XOF';
alter table public.department_budgets add column if not exists team_id uuid, add column if not exists project_name text, add column if not exists activity_name text, add column if not exists period_start date, add column if not exists period_end date, add column if not exists scenario_name text not null default 'Base', add column if not exists forecast_amount numeric not null default 0, add column if not exists variance_reason text, add column if not exists risk_level text not null default 'normal', add column if not exists last_reviewed_at timestamptz;
alter table public.strategic_actions add column if not exists project_name text, add column if not exists priority text not null default 'normal', add column if not exists risk_description text, add column if not exists milestone_name text, add column if not exists dependency_notes text, add column if not exists corrective_action text, add column if not exists last_reviewed_at timestamptz;
do $$ begin if not exists(select 1 from pg_constraint where conname='strategic_plans_horizon_check') then alter table public.strategic_plans add constraint strategic_plans_horizon_check check(planning_horizon in ('annual','multi_year','quarterly','operational')); end if; if not exists(select 1 from pg_constraint where conname='strategic_plans_version_positive_check') then alter table public.strategic_plans add constraint strategic_plans_version_positive_check check(version_number>0); end if; if not exists(select 1 from pg_constraint where conname='department_budgets_risk_level_check') then alter table public.department_budgets add constraint department_budgets_risk_level_check check(risk_level in ('low','normal','high','critical')); end if; if not exists(select 1 from pg_constraint where conname='strategic_actions_priority_check') then alter table public.strategic_actions add constraint strategic_actions_priority_check check(priority in ('low','normal','high','critical')); end if; end $$;
create index if not exists idx_strategic_plans_year_status on public.strategic_plans(fiscal_year,status);
create index if not exists idx_department_budgets_plan_department on public.department_budgets(plan_id,department);
create index if not exists idx_department_budgets_period on public.department_budgets(period_start,period_end);
create index if not exists idx_strategic_actions_plan_status_due on public.strategic_actions(plan_id,status,due_on);
create index if not exists idx_strategic_actions_team_due on public.strategic_actions(team_id,due_on);
create or replace function public.touch_planning_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new; end $$;
drop trigger if exists trg_strategic_plans_updated_at on public.strategic_plans; create trigger trg_strategic_plans_updated_at before update on public.strategic_plans for each row execute function public.touch_planning_updated_at();
drop trigger if exists trg_department_budgets_updated_at on public.department_budgets; create trigger trg_department_budgets_updated_at before update on public.department_budgets for each row execute function public.touch_planning_updated_at();
drop trigger if exists trg_strategic_actions_updated_at on public.strategic_actions; create trigger trg_strategic_actions_updated_at before update on public.strategic_actions for each row execute function public.touch_planning_updated_at();
create or replace view public.v_planning_budget_control with (security_invoker=true) as select b.id as budget_id,b.plan_id,p.fiscal_year,p.title as plan_title,p.status as plan_status,b.department,b.team_id,b.category,b.project_name,b.activity_name,b.budget_initial,b.budget_revised,b.committed_amount,b.actual_amount,b.forecast_amount,b.revenue_forecast,b.actual_revenue,(b.budget_revised-b.committed_amount) as uncommitted_budget,(b.budget_revised-b.actual_amount) as remaining_budget,(b.actual_amount-b.budget_revised) as overspend_amount,case when b.budget_revised=0 then 0 else round((b.actual_amount/b.budget_revised)*100,2) end as execution_percent,(b.actual_revenue-b.revenue_forecast) as revenue_variance,b.risk_level,b.status as budget_status,b.variance_reason,b.last_reviewed_at from public.department_budgets b join public.strategic_plans p on p.id=b.plan_id;
